import { createHash } from "node:crypto";
export const runtime = "nodejs";
export const maxDuration = 300;

/** One-shot diagnosis of dictation: a fixed Portuguese sample through each model and setting. Removed in the next deploy. */
const TOKEN_SHA256 = "42ef81897014b12460ffe5029f8e74b252f99f5de45b55e350e34855514e5a9a";
const WEBM = "";
const M4A = "";
const CASES: { model: string; format: "webm" | "m4a"; language?: string; zdr: boolean }[] = [
  { model: "microsoft/mai-transcribe-2", format: "webm", language: "pt", zdr: true },
  { model: "microsoft/mai-transcribe-2", format: "webm", zdr: true },
  { model: "microsoft/mai-transcribe-2", format: "webm", language: "pt-BR", zdr: true },
  { model: "microsoft/mai-transcribe-2", format: "m4a", language: "pt", zdr: true },
  { model: "openai/whisper-large-v3-turbo", format: "webm", language: "pt", zdr: true },
  { model: "openai/whisper-large-v3", format: "webm", language: "pt", zdr: true },
  { model: "mistralai/voxtral-mini-transcribe", format: "webm", language: "pt", zdr: true },
  { model: "mistralai/voxtral-mini-transcribe", format: "webm", language: "pt", zdr: false },
  { model: "openai/whisper-large-v3-turbo", format: "m4a", language: "pt", zdr: true },
];

export async function GET(request: Request) {
  const token = request.headers.get("x-once-token") ?? "";
  if (createHash("sha256").update(token).digest("hex") !== TOKEN_SHA256) return new Response(null, { status: 404 });
  const results = [];
  for (const c of CASES) {
    const started = Date.now();
    try {
      const res = await fetch("https://openrouter.ai/api/v1/audio/transcriptions", {
        method: "POST",
        headers: { Authorization: "Bearer " + process.env.OPENROUTER_API_KEY, "Content-Type": "application/json", "X-Title": "Anuntech Console" },
        body: JSON.stringify({
          model: c.model,
          input_audio: { data: c.format === "webm" ? WEBM : M4A, format: c.format },
          ...(c.language ? { language: c.language } : {}),
          ...(c.zdr ? { provider: { zdr: true } } : {}),
        }),
        signal: AbortSignal.timeout(25_000),
      });
      const body = (await res.json().catch(() => null)) as { text?: string; error?: { message?: string; metadata?: unknown } } | null;
      results.push({ ...c, status: res.status, ms: Date.now() - started, text: body?.text?.slice(0, 120) ?? null, error: body?.error ? JSON.stringify(body.error).slice(0, 400) : null });
    } catch (error) {
      results.push({ ...c, status: 0, ms: Date.now() - started, error: error instanceof Error ? error.message : "falhou" });
    }
  }
  return Response.json({ results });
}
